    /* 国・地域の名前（文の形の中で使う） */
    const CN = (x: string, d: any) => String(x).split(/([・、／])/).map(s => /^[・、／]$/.test(s) ? (I18N.lang === "zh" ? s : (s === "／" ? " / " : ", ")) : tr(s, d)).join("");
    /* ── 見本を開いた・切り替えたときのトースト（xi18n-76）。会社名は固有名詞（辞書にあれば訳す） ── */
    P(/^(.+)の環境を作成しました：(.+)$/, (m: any, d: any) => "Created the " + tr(m[1], d) + " environment: " + tr(m[2], d), (m: any, d: any) => "已创建" + tr(m[1], d) + "环境：" + tr(m[2], d), (m: any, d: any) => "Se creó el entorno de " + tr(m[1], d) + ": " + tr(m[2], d));
    P(/^(.+)のサンプル環境を作成しました：(.+)（1日目の状態）$/, (m: any, d: any) => "Created the " + tr(m[1], d) + " sample environment: " + tr(m[2], d) + " (day-1 state)", (m: any, d: any) => "已创建" + tr(m[1], d) + "示例环境：" + tr(m[2], d) + "（第1天的状态）", (m: any, d: any) => "Se creó el entorno de ejemplo de " + tr(m[1], d) + ": " + tr(m[2], d) + " (estado del día 1)");
    P(/^(.+)のサンプル環境（(.+)）に切り替えました$/, (m: any, d: any) => "Switched to the " + tr(m[1], d) + " sample environment (" + tr(m[2], d) + ")", (m: any, d: any) => "已切换到" + tr(m[1], d) + "示例环境（" + tr(m[2], d) + "）", (m: any, d: any) => "Se cambió al entorno de ejemplo de " + tr(m[1], d) + " (" + tr(m[2], d) + ")");
    P(/^(.+)／(.+) に切り替えました$/, (m: any, d: any) => "Switched to " + tr(m[1], d) + " / " + tr(m[2], d), (m: any, d: any) => "已切换到 " + tr(m[1], d) + "／" + tr(m[2], d), (m: any, d: any) => "Se cambió a " + tr(m[1], d) + " / " + tr(m[2], d));
    P(/^「(.+)」に切り替えました$/, (m: any, d: any) => "Switched to “" + tr(m[1], d) + "”", (m: any, d: any) => "已切换到“" + tr(m[1], d) + "”", (m: any, d: any) => "Se cambió a “" + tr(m[1], d) + "”");
    /* ── 数・国名・日付などが入る文の形（3言語）。中の言葉は辞書で訳す（tr）。数字・日付・事実はそのまま ── */
    const L3 = (en: string, zh: string, es: string) => I18N.lang === "zh" ? zh : I18N.lang === "es" ? es : en;
    const F = (re: RegExp, f: (m: any, d: any) => any) => { PATS.push({ re, en: f, zh: f, es: f }); };
    const known = (x: string, d: any) => { const t = tr(x, d); if (t !== String(x))
        return t; if (!JPRE.test(String(x)) || (I18N.lang === "zh" && !/[ぁ-ゖァ-ヺ]/.test(String(x))))
        return String(x); return null; };
    const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const MES = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
    const WD: any = { "日": ["Sun", "周日", "dom"], "月": ["Mon", "周一", "lun"], "火": ["Tue", "周二", "mar"], "水": ["Wed", "周三", "mié"], "木": ["Thu", "周四", "jue"], "金": ["Fri", "周五", "vie"], "土": ["Sat", "周六", "sáb"] };
    const sep = () => I18N.lang === "zh" ? "・" : " · ";
    /* 左メニュー・上の帯 */
    P(/^版 ([\d.]+)（build (\w+)）$/, "Version $1 (build $2)", "版本 $1（build $2）", "Versión $1 (build $2)");
    P(/^要対応 (\d+)$/, "Action needed $1", "待处理 $1", "Requiere acción $1");
    P(/^要対応 (\d+)件（相手の返信に、まだ返していない案件。案件の数ではありません）$/, "Action needed: $1 (cases where the buyer replied and you have not answered yet; not the number of cases)", "待处理 $1件（对方已回复而您尚未回复的案件，不是案件总数）", "Requiere acción: $1 (casos en que el comprador respondió y usted aún no; no es el número de casos)");
    F(/^いま：(.+)・見本 (\d+)社$/, (m, d) => L3("Now: " + CN(m[1], d) + " · samples: " + m[2] + " companies", "当前：" + CN(m[1], d) + "・示例 " + m[2] + "家", "Ahora: " + CN(m[1], d) + " · ejemplos: " + m[2] + " empresas"));
    F(/^いま：(.+)$/, (m, d) => L3("Now: ", "当前：", "Ahora: ") + tr(m[1], d));
    F(/^次：(.+)$/, (m, d) => L3("Next: ", "下一步：", "Siguiente: ") + tr(m[1], d));
